commit 83a9c210feffefa24d7f6ab2fbce64792c25946b
Author: K.Kosako <kosako@sofnec.co.jp>
Date:   Tue Jan 21 10:34:50 2020 +0900

    don't optimize look-behind if it includes captures or anchors
---
 src/regcomp.c | 7 +++++++
 1 file changed, 7 insertions(+)

diff --git a/src/regcomp.c b/src/regcomp.c
index 6740d97..b79da4b 100644
--- a/src/regcomp.c
+++ b/src/regcomp.c
@@ -831,6 +831,8 @@ node_char_len1(Node* node, regex_t* reg, MinMaxCharLen* ci, ScanEnv* env,
           if (ci->min_is_sure != 0)
             NODE_STATUS_ADD(node, FIXED_CLEN_MIN_SURE);
         }
+        /* can't optimize look-behind if capture exists. */
+        ci->min_is_sure = FALSE;
         break;
       case BAG_OPTION:
       case BAG_STOP_BACKTRACK:
@@ -868,6 +870,11 @@ node_char_len1(Node* node, regex_t* reg, MinMaxCharLen* ci, ScanEnv* env,
     break;

   case NODE_ANCHOR:
+    mmcl_set(ci, 0);
+    /* can't optimize look-behind if anchor exists. */
+    ci->min_is_sure = FALSE;
+    break;
+
   case NODE_GIMMICK:
   zero:
     mmcl_set(ci, 0);

commit d4eabacaa1cba259e901c7046c40f8727a6bd21d
Author: K.Kosako <kosako@sofnec.co.jp>
Date:   Tue Jan 21 08:45:02 2020 +0900

    backref node min len is sure only if length is fixed
---
 src/regcomp.c | 4 ++--
 1 file changed, 2 insertions(+), 2 deletions(-)

diff --git a/src/regcomp.c b/src/regcomp.c
index c1eb72e..6740d97 100644
--- a/src/regcomp.c
+++ b/src/regcomp.c
@@ -897,13 +897,13 @@ node_char_len1(Node* node, regex_t* reg, MinMaxCharLen* ci, ScanEnv* env,

       backs = BACKREFS_P(br);
       r = node_char_len1(mem_env[backs[0]].mem_node, reg, ci, env, level);
-      ci->min_is_sure = FALSE;
       if (r < 0) break;
+      if (! mmcl_fixed(ci)) ci->min_is_sure = FALSE;

       for (i = 1; i < br->back_num; i++) {
         r = node_char_len1(mem_env[backs[i]].mem_node, reg, &tci, env, level);
         if (r < 0) break;
-        tci.min_is_sure = FALSE;
+        if (! mmcl_fixed(&tci)) tci.min_is_sure = FALSE;
         mmcl_alt_merge(ci, &tci);
       }
     }

